// The first argument is typically a *testing.T value.
func NewTenantApi(t interface {
	mock.TestingT
	Cleanup(func())
}) *TenantApi {
	mock := &TenantApi{}
	mock.Mock.Test(t)

	t.Cleanup(func() { mock.AssertExpectations(t) })

	return mock
}
